from griffe import load
from griffe.extensions import Extension
from griffe.docstrings import Docstring


class AppendCheckedExtension(Extension):
    """Extension that appends ' [checked]' to function docstrings."""

    def on_parsed_object(self, obj):
        """Called after an object is parsed."""
        if obj.is_function:
            if obj.docstring:
                obj.docstring.value += " [checked]"
            else:
                obj.docstring = Docstring(" [checked]")


# Create extension instance and load package with it
extension = AppendCheckedExtension("append_checked")
module = load("mypkg", extensions=[extension])

# Verify results
for name, obj in module.members.items():
    if obj.is_function:
        doc_text = obj.docstring.value if obj.docstring else "(no docstring)"
        print(f"Function {name}: {doc_text}")
